const can=p=>!!user?.is_admin||!!user?.permissions?.includes(p);const tr=k=>(lang==='ar'?AR:EN)[k]||k,st=k=>(lang==='ar'?STATUS_AR:STATUS_EN)[k]||String(k||'—').replaceAll('_',' '),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString(lang==='ar'?'ar-SA':'en-US'),money=n=>Number(n||0).toLocaleString(lang==='ar'?'ar-SA':'en-US',{maximumFractionDigits:2,minimumFractionDigits:2});
function toast(message){let x=document.getElementById('toast');x.textContent=message;x.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>x.style.display='none',5000)}
function detailError(j){if(typeof j.detail==='string')return j.detail;if(j.detail?.message)return `${j.detail.message} (PO ${j.detail.po_number})`;return JSON.stringify(j.detail||j)}
async function api(url,method='GET',body){const options={method,headers:{'X-Logistics-Request':'1'}};if(body!==undefined){if(body instanceof FormData)options.body=body;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}}const r=await fetch('/api/'+url,options);const j=await r.json().catch(()=>({detail:'Request failed'}));if(!r.ok){let e=new Error(detailError(j));e.detail=j.detail;throw e}return j}
function field(name,label,type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" ${extra}></label>`}function select(name,label,options,extra=''){return `<label>${esc(label)}<select name="${name}" ${extra}>${options}</select></label>`}function choices(values,selected){return values.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('')}function table(head,records){return records.length?`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${records.join('')}</tbody></table></div>`:`<div class="empty">${tr('noRows')}</div>`}
function shell(content,title,subtitle=''){let nav=[['control','control'],['reports','reports'],['open','open'],['inventory','inventory'],['imports','imports'],['tasks','tasks'],['admin','admin']].filter(([key])=>key==='control'||key==='admin'||(key==='open'?(can('pos_edit')||can('invoice_edit')||can('issue_edit')):can(({inventory:'inventory_edit',reports:'reports_view',imports:'imports_apply',tasks:'task_edit'})[key])));document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="shell"><header class="top"><div class="brand"><div class="brand-icon">S</div><div><h1>Sial Logistics</h1><small>PO · Inventory · Delivery</small></div></div><div class="top-actions"><span class="small">${esc(user?.username||'')}</span><button onclick="toggleLang()">${lang==='en'?'العربية':'English'}</button><button onclick="logout()">${tr('signOut')}</button></div></header><div class="layout"><aside class="side">${nav.map(([key,label])=>`<button class="${view===key?'active':''}" onclick="go('${key}')">${tr(label)}</button>`).join('')}</aside><main class="main"><div class="page-title"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div>${content}</main></div></div>`}
async function refresh(){try{user=await api('auth/me');data=await api('dashboard');if(user.is_admin||user.permissions.includes('reports_view')){[report,ops,statusOptions]=await Promise.all([api('reports'),api('reports/operations'),api('status-options')])}else{report={};ops={};statusOptions=await api('status-options')}if(user.is_admin)users=await api('auth/users');if(user.is_admin||can('task_edit'))asnAssignments=await api('asn-assignments');if(!user.is_admin&&view==='admin')view='control';render()}catch(e){if(e.message==='Sign in required')loginView();else toast(e.message)}}function go(x){view=x;render()}function render(){if(!user)return loginView();if(view==='control')return controlView();if(view==='open'){poView();showNextNumber();return}if(view==='inventory')return inventoryView();if(view==='reports')return reportView();if(view==='imports')return importsView();if(view==='tasks')return tasksView();return adminView()}
function loginView(reset=false){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="login"><div class="brand" style="justify-content:center;margin-bottom:20px"><div class="brand-icon">S</div><h1>Sial Logistics</h1></div><div class="card"><h3>${reset?tr('forgot'):tr('signIn')}</h3><form class="form one" onsubmit="${reset?'requestReset':'login'}(event)">${reset?field('email','Email','email','required'):field('username',tr('user'),'text','required')+field('password',tr('password'),'password','required')}<button class="primary">${reset?tr('sendReset'):tr('signIn')}</button></form><p><button class="secondary" onclick="loginView(${!reset})">${reset?tr('signIn'):tr('forgot')}</button></p></div></div>`}async function login(e){e.preventDefault();try{await api('auth/login','POST',Object.fromEntries(new FormData(e.target)));await refresh()}catch(x){toast(x.message)}}async function logout(){await api('auth/logout','POST',{});user=null;loginView()}async function requestReset(e){e.preventDefault();try{await api('auth/reset-request','POST',Object.fromEntries(new FormData(e.target)));toast('Check your email for a reset link.')}catch(x){toast(x.message)}}function toggleLang(){lang=lang==='en'?'ar':'en';localStorage.setItem('sial-lang',lang);render()}
function controlView(){let reminders=data.reminders||[],urgent=data.urgent||[];let cards=`<div class="stats"><div class="stat"><span>${tr('urgent')}</span><strong>${urgent.length}</strong></div><div class="stat"><span>${tr('reminders')}</span><strong>${reminders.length}</strong></div><div class="stat"><span>${tr('outstanding')}</span><strong>${(data.pos||[]).filter(x=>!x.archived&&x.status!=='delivered'&&x.status!=='gr_issued').length}</strong></div></div>`;let lineRows=x=>x.map(p=>`<tr><td><button class="secondary" onclick="openPO(${p.po_id})">${esc(p.number)}</button></td><td>${esc(p.item_code)} · ${fmt(p.ordered_qty-p.delivered_qty)}</td><td>${esc(p.region||'—')}</td><td>${esc(p.due_date)}</td><td>${p.days_to_due<0?`${fmt(-p.days_to_due)} days late`:fmt(p.days_to_due)}</td></tr>`);shell(cards+`<div class="grid"><div class="card"><h3>🚨 ${tr('urgent')}</h3>${table([tr('po'),tr('item'),tr('region'),tr('due'),tr('date')],lineRows(urgent))}</div><div class="card"><h3>${tr('reminders')}</h3>${table([tr('po'),tr('item'),tr('region'),tr('due'),tr('date')],lineRows(reminders))}</div></div>`,tr('control'))}
function openPO(id){selectedPO=Number(id);view='open';render()}
function filteredPOs(){return (data.pos||[]).filter(p=>(!regionFilter||p.region===regionFilter)&&(poFilter==='archive'?p.archived:poFilter==='all'?!p.archived:poFilter==='delivered'?!p.archived&&['delivered','gr_issued'].includes(p.status):!p.archived&&Number(p.ordered_qty||0)>Number(p.delivered_qty||0))).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||a.number.localeCompare(b.number))}
function togglePOSelection(id,checked){if(checked)selectedIds.add(id);else selectedIds.delete(id);let count=document.getElementById('selection-count');if(count)count.textContent=selectedIds.size}
function toggleAllPOs(checked){for(let p of filteredPOs()){if(checked)selectedIds.add(p.id);else selectedIds.delete(p.id)}render()}
function poView(){
  const pos=filteredPOs();
  const regions=[...new Set((data.pos||[]).map(x=>x.region).filter(Boolean))].sort();
  for(const id of [...selectedIds])if(!pos.some(p=>p.id===id))selectedIds.delete(id);
  const regionOptions=choices([['',tr('allRegions')],...regions.map(x=>[x,x])],regionFilter);
  const stageOptions=choices([['outstanding',tr('allOutstanding')],['delivered',st('delivered')+' / '+st('gr_issued')],['all',tr('active')],['archive',tr('paidArchive')]],poFilter);
  const filter=`<div class="card compact"><div class="split">${select('region',tr('region'),regionOptions,'onchange="regionFilter=this.value;selectedPO=null;selectedIds.clear();render()"')}${select('stage',tr('status'),stageOptions,'onchange="poFilter=this.value;selectedPO=null;selectedIds.clear();render()"')}<span class="pill">${fmt(pos.length)} POs</span></div></div>`;
  const rows=pos.map(p=>{const lines=(data.lines||[]).filter(x=>x.po_number===p.number);const assigned=(data.assigned_invoice_numbers||[]).find(x=>x.po_id===p.id)?.number||p.source_invoice_reference||'—';return `<tr class="${selectedPO===p.id?'selected-row':''}"><td><input type="checkbox" aria-label="Select ${esc(p.number)}" ${selectedIds.has(p.id)?'checked':''} onchange="togglePOSelection(${p.id},this.checked)"></td><td class="code">${esc(p.number)}</td><td>${esc(p.due_date||'—')}</td><td>${esc([...new Set(lines.map(x=>x.item_code))].join(', ')||'—')}</td><td>${fmt(Math.max(0,(p.ordered_qty||0)-(p.delivered_qty||0)))}</td><td>${money(p.value)}</td><td>${esc(assigned)}</td><td><span class="pill">${st(p.status)}</span></td><td><button class="secondary" onclick="openPO(${p.id})">${tr('details')}</button></td></tr>`});
  const list=`<div class="card"><div class="card-title"><h3>${tr('outstandingPOs')}</h3><button class="secondary" onclick="toggleAllPOs(true)">${tr('selectAll')}</button></div>${table(['',tr('po'),tr('due'),tr('item'),tr('outstanding'),tr('value'),tr('invoiceAssigned'),tr('status'),''],rows)}</div>`;
  const assign=user?.is_admin&&poFilter==='outstanding'?`<div class="card compact"><h3>${tr('assignASN')}</h3><form class="assignment-form" onsubmit="assignASN(event)"><span class="pill"><span id="selection-count">${selectedIds.size}</span> ${tr('selected')}</span>${select('assigned_to',tr('assignTo'),choices([['',tr('noAssignee')],...users.filter(x=>x.active&&!x.is_admin).map(x=>[x.username,x.username])]),'required')}${field('due_date',tr('due'),'date','required')}<button class="primary">${tr('assignASN')}</button></form></div>`:'';
  const p=(data.pos||[]).find(x=>x.id===selectedPO);
  shell(filter+assign+list+(p?`<h3 class="section-label">${tr('details')} · ${esc(p.number)}</h3>`+poDetails(p):''),tr('outstandingPOs'),tr('reportHelp'));
}
async function assignASN(e){e.preventDefault();if(!selectedIds.size)return toast('Select at least one PO');let f=e.target;if(!f.assigned_to.value)return toast(tr('noAssignee'));let ids=[...selectedIds];if(!confirm(`${tr('assignASN')}: ${ids.length} POs?`))return;try{let j=await api('asn-assignments','POST',{po_ids:ids,assigned_to:f.assigned_to.value,due_date:f.due_date.value});selectedIds.clear();await refresh();toast(j.assignments.map(x=>`${x.po_number}: ${x.invoice_number}`).join(' · '))}catch(x){toast(x.message)}}
function poDetails(p){let lines=(data.lines||[]).filter(x=>x.po_number===p.number),invoices=(data.invoices||[]).filter(x=>x.po_id===p.id),issues=(data.issues||[]).filter(x=>x.po_id===p.id),docs=(data.documents||[]).filter(x=>x.po_id===p.id);let details=`<div class="card"><div class="details">${[[tr('po'),p.number],[tr('region'),p.region||'—'],[tr('address'),p.address||'—'],[tr('value'),money(p.value)],[tr('status'),st(p.status)],[tr('invoiceStage'),st(p.invoice_status)],[tr('due'),p.due_date||'—'],[tr('outstanding'),fmt(Math.max(0,(p.ordered_qty||0)-(p.delivered_qty||0)))],[tr('sourceInvoice'),p.source_invoice_reference||'—'],[tr('sourceRemaining'),p.source_remaining||'—'],[tr('sourceRemarks'),p.source_remarks||'—'],[tr('sourceInfo'),p.source_status||'—'],[tr('invoiceStage'),p.source_invoice_status||'—'],['Customer',p.customer||'—'],['Customer PO',p.customer_po||'—'],['ASN #',p.asn_number||'—'],['ASN date',p.asn_date||'—'],['ASN URL',p.asn_link||'—']].map(([k,v])=>`<div class="detail"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><h3>${tr('item')}</h3>${table(['#',tr('item'),tr('quantity'),tr('boxes'),tr('pallets'),tr('due'),tr('address')],lines.map(x=>`<tr><td>${esc(x.line_no)}</td><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td><td>${(x.quantity/x.pcs_per_box).toFixed(2)}</td><td>${x.boxes_per_pallet?(x.quantity/x.pcs_per_box/x.boxes_per_pallet).toFixed(2):'—'}</td><td>${esc(x.due_date)}</td><td>${esc(x.address||p.address)}</td></tr>`))}</div><div class="card"><h3>${tr('regionRows')}</h3>${table([tr('item'),tr('quantity'),tr('outstanding'),tr('due'),tr('status'),tr('invoice'),tr('address')],(data.regional_rows||[]).filter(r=>r.po_number===p.number).map(r=>`<tr><td>${esc(r.item_text)}</td><td>${esc(r.planned_qty)}</td><td>${esc(r.left_qty)}</td><td>${esc(r.due_date)}</td><td>${esc(r.status)}</td><td>${esc(r.invoice_reference)}</td><td>${esc(r.address)}</td></tr>`))}</div>`;let statusForm=`<div class="card"><h3>${tr('status')}</h3><form class="form" onsubmit="savePOStatus(event,${p.id})">${select('status',tr('status'),choices((statusOptions.po||[]).map(x=>[x,st(x)]),p.status))}${field('reason',tr('reason'))}${field('asn_number','ASN #','text',`value="${esc(p.asn_number||'')}"`)}${field('asn_date','ASN '+tr('date'),'date',`value="${esc(p.asn_date||'')}"`)}${field('asn_link','ASN URL','url',`value="${esc(p.asn_link||'')}"`)}<label class="full file-input">GR / ASN PDF<input type="file" name="file" accept=".pdf"></label><div class="full actions"><button class="primary">${tr('save')}</button><span class="hint">GR: PDF required. ASN rejected: PDF or N/A. Reopen delivered PO: admin and reason required.</span></div></form></div>`;let stageForm=`<div class="card"><h3>${tr('invoiceStage')}</h3><form class="form" onsubmit="saveInvoiceStage(event,${p.id})">${select('status',tr('invoiceStage'),choices((statusOptions.invoice||[]).map(x=>[x,st(x)]),p.invoice_status))}${field('reason',tr('reason'))}<button class="primary">${tr('save')}</button></form></div>`;let marketplaceForm=p.kind==='marketplace'?`<div class="card"><h3>${tr('marketplaceStage')}</h3><form class="form" onsubmit="saveMarketplaceStage(event,${p.id})">${select('status',tr('marketplaceStage'),choices([['delivered',st('delivered')],['rcv_returned',st('rcv_returned')]],p.marketplace_status))}${field('reason',tr('reason'))}<button class="primary">${tr('save')}</button></form></div>`:'';let invoicePanel=`<div class="card"><h3>${tr('bookInvoice')}</h3><p class="hint">${tr('nextNumber')}: <strong id="next-number">…</strong>${p.ordered_qty<=p.delivered_qty?' · '+tr('alreadyDelivered'):''}</p><form onsubmit="bookInvoice(event,${p.id})" class="form"><div>${field('number',tr('invoiceNumber'),'text','required')}</div>${field('value',tr('invoiceValue'),'number','min="0" step="0.01"')}<div class="full">${lines.map(x=>`<div class="invoice-line"><label>${esc(x.line_no)} · ${esc(x.item_code)}</label>${select('batch_'+x.id,tr('batch'),choices([['','—'],...(data.batches||[]).filter(b=>b.item_code===x.item_code).map(b=>[b.id,`${b.batch_no} (${fmt(b.quantity)})`])]))}${field('qty_'+x.id,tr('quantity'),'number','min="0" placeholder="0"')}</div>`).join('')}</div><div class="full actions"><button class="primary" ${p.ordered_qty<=p.delivered_qty||p.archived?'disabled':''}>${tr('bookInvoice')}</button></div></form><h3 style="margin-top:25px">${tr('invoice')}</h3>${table([tr('invoiceNumber'),tr('quantity'),tr('status'),'Action'],invoices.map(i=>`<tr><td class="code">${esc(i.number)}</td><td>${fmt(i.quantity)}</td><td>${st(i.status)}</td><td>${invoiceNext(i)}</td></tr>`))}</div>`;let docsPanel=`<div class="card"><h3>${tr('documents')}</h3>${docs.length?docs.map(d=>`<div class="list-row"><span>${esc(d.filename)}</span><a class="button secondary" href="/api/documents/${d.id}">${tr('download')}</a></div>`).join(''):`<p class="muted">${tr('noRows')}</p>`}</div>`;let issuePanel=`<div class="card"><h3>${tr('issue')}</h3><form class="form" onsubmit="addIssue(event,${p.id})">${select('type',tr('problemType'),choices(['Stock shortage','Technical','Delivery','ASN','Payment','Other'].map(x=>[x,x])))}${field('ticket_no',tr('ticket'))}<label class="full">${tr('description')}<textarea name="description" required></textarea></label><button class="primary">${tr('addIssue')}</button></form>${issues.length?table([tr('problemType'),tr('ticket'),tr('description')],issues.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.ticket_no)}</td><td>${esc(x.description)}</td></tr>`)):''}</div>`;return details+`<div class="grid">${can('pos_edit')?statusForm:''}${can('invoice_edit')?stageForm:''}${can('pos_edit')?marketplaceForm:''}${can('invoice_edit')?invoicePanel:''}${can('pos_edit')?docsPanel:''}${can('issue_edit')?issuePanel:''}</div>`}
function invoiceNext(i){const map={booked:'dispatched',dispatched:'delivered',delivered:'gr_issued',gr_issued:'uploaded',uploaded:'paid'};return map[i.status]?`<button class="secondary" onclick="advanceInvoice(${i.id},'${map[i.status]}')">${st(map[i.status])}</button>`:'—'}
async function advanceInvoice(id,status){if(!confirm(`${tr('confirm')}: ${st(status)}?`))return;try{await api(`invoices/${id}/status`,'PATCH',{status,confirmed:true});await refresh();toast(tr('save'))}catch(e){toast(e.message)}}async function savePOStatus(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;let f=new FormData(e.target);f.set('confirmed','true');if(!f.get('file')?.name)f.delete('file');try{await api(`pos/${id}/operational-status`,'POST',f);await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function saveInvoiceStage(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;try{await api(`pos/${id}/invoice-stage`,'PATCH',{...Object.fromEntries(new FormData(e.target)),confirmed:true});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function saveMarketplaceStage(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;try{await api(`pos/${id}/marketplace-stage`,'PATCH',{...Object.fromEntries(new FormData(e.target)),confirmed:true});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function addIssue(e,id){e.preventDefault();try{await api('issues','POST',{...Object.fromEntries(new FormData(e.target)),po_id:id});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function bookInvoice(e,id){e.preventDefault();let f=e.target,lines=(data.lines||[]).filter(x=>x.po_number===(data.pos||[]).find(p=>p.id===id)?.number),entries=[];for(let l of lines){let qty=Number(f.elements['qty_'+l.id]?.value||0),batch=Number(f.elements['batch_'+l.id]?.value||0);if(qty>0){if(!batch)return toast('Choose a batch for every booked quantity');entries.push({po_line_id:l.id,batch_id:batch,quantity:qty})}}if(!entries.length)return toast('Enter at least one quantity');if(!confirm(tr('confirm')+'?'))return;try{await api('invoices','POST',{po_id:id,number:f.elements.number.value,value:Number(f.elements.value.value||0),lines:entries});await refresh();toast(tr('save'))}catch(x){if(x.detail?.invoice_id&&confirm(`${x.message}\nTransfer the existing booked invoice to this PO?`)){try{await api(`invoices/${x.detail.invoice_id}/transfer`,'POST',{target_po_id:id,confirmed:true});await refresh()}catch(y){toast(y.message)}}else toast(x.message)}}
async function showNextNumber(){let p=(data.pos||[]).find(x=>x.id===selectedPO),node=document.getElementById('next-number');if(!p||!node)return;try{let j=await api(`invoices/next-number?po_id=${p.id}`);node.textContent=j.next_number;let input=document.querySelector('input[name=number]');if(input&&!input.value)input.value=j.next_number}catch(e){node.textContent='—'}}
function inventoryView(){let stock=data.stock||[],batches=data.batches||[];let top=`<div class="card"><h3>${tr('startingStock')}</h3><p class="hint">${tr('stockHelp')}</p><form class="form" onsubmit="previewStock(event)"><label class="file-input full">${tr('stockWorkbook')}<input name="file" type="file" accept=".xlsx" required></label><button class="primary">${tr('preview')}</button></form><div id="stock-preview"></div></div>`;let inventory=`<div class="card"><h3>${tr('inventory')}</h3>${table([tr('item'),tr('physical'),tr('booked'),tr('free'),tr('boxes'),tr('pallets')],stock.map(x=>`<tr><td class="code">${esc(x.code)}</td><td>${fmt(x.physical)}</td><td>${fmt(x.booked)}</td><td><strong>${fmt(x.free)}</strong></td><td>${fmt(x.pcs_per_box)} pcs</td><td>${fmt(x.boxes_per_pallet)}</td></tr>`))}</div><div class="card"><h3>${tr('batch')}</h3>${table([tr('item'),tr('batch'),tr('quantity'),tr('mfg'),tr('expiry')],batches.map(x=>`<tr><td>${esc(x.item_code)}</td><td class="code">${esc(x.batch_no)}</td><td>${fmt(x.quantity)}</td><td>${esc(x.mfg_date)}</td><td>${esc(x.expiry_date)}</td></tr>`))}</div>`;let receive=`<div class="card"><h3>${tr('receive')}</h3><form class="form" onsubmit="receiveBatch(event)">${select('item_code',tr('item'),choices(stock.map(x=>[x.code,x.code])))}${field('batch_no',tr('batch'),'text','required')}${field('quantity',tr('quantity'),'number','min="1" required')}${field('mfg_date',tr('mfg'),'date')}${field('expiry_date',tr('expiry'),'date')}<button class="primary">${tr('receive')}</button></form></div>`;shell(top+inventory+`<div class="grid">${receive}<div class="card"><h3>${tr('item')}</h3><form class="form" onsubmit="addItem(event)">${field('code',tr('item'),'text','required')}${field('description',tr('description'))}${field('pcs_per_box',tr('boxes'),'number','min="1" required')}${field('boxes_per_pallet',tr('pallets'),'number','min="0" required')}<button class="primary">${tr('save')}</button></form></div></div>`+`<div class="card"><h3>Return stock</h3><form class="form" onsubmit="returnStock(event)">${select('invoice_id',tr('invoice'),choices((data.invoices||[]).map(i=>[i.id,i.number])))}${select('batch_id',tr('batch'),choices(batches.map(b=>[b.id,`${b.item_code} · ${b.batch_no}`])))}${field('quantity',tr('quantity'),'number','min="1" required')}<button class="primary">${tr('save')}</button></form></div>`,tr('inventory'))}
async function addItem(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.pcs_per_box=Number(x.pcs_per_box);x.boxes_per_pallet=Number(x.boxes_per_pallet);try{await api('items','POST',x);await refresh()}catch(y){toast(y.message)}}async function receiveBatch(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.quantity=Number(x.quantity);try{await api('batches','POST',x);await refresh()}catch(y){toast(y.message)}}async function returnStock(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(!confirm(tr('confirm')+'?'))return;try{await api(`invoices/${x.invoice_id}/returns`,'POST',{batch_id:Number(x.batch_id),quantity:Number(x.quantity),confirmed:true});await refresh()}catch(y){toast(y.message)}}async function previewStock(e){e.preventDefault();let file=e.target.file.files[0],fd=new FormData();fd.set('file',file);try{let j=await api('inventory/starting-preview','POST',fd);previewState={kind:'stock',file,fingerprint:j.fingerprint};document.getElementById('stock-preview').innerHTML=previewPanel(j,'applyStock()')}catch(x){toast(x.message)}}async function applyStock(){if(!previewState||previewState.kind!=='stock'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();fd.set('file',previewState.file);fd.set('fingerprint',previewState.fingerprint);try{let j=await api('inventory/starting-apply','POST',fd);await refresh();toast(`${j.rows} rows imported`)}catch(x){toast(x.message)}}
function reportView(){let regions=ops.regions||[],choice=choices([['',tr('allRegions')],...regions.map(r=>[r,r])],regionFilter),byRegion=(ops.by_region_item||[]).filter(x=>!regionFilter||x.region===regionFilter),pick=(ops.warehouse_pick_list||[]).filter(x=>!regionFilter||x.region===regionFilter);shell(`<div class="card"><div class="split">${select('region',tr('region'),choice,'onchange="regionFilter=this.value;render()"')}<button class="secondary" onclick="exportPickList()">${tr('exportCSV')} · ${tr('warehouse')}</button><button class="secondary" onclick="exportReport('item')">${tr('exportCSV')} · ${tr('byItem')}</button><button class="secondary" onclick="exportReport('region')">${tr('exportCSV')} · ${tr('byRegionItem')}</button></div></div><div class="grid"><div class="card"><h3>${tr('byItem')}</h3><p class="hint">${tr('reportHelp')}</p>${table([tr('item'),tr('quantity')],(ops.by_item||[]).map(x=>`<tr><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td></tr>`))}</div><div class="card"><h3>${tr('byRegionItem')}</h3>${table([tr('region'),tr('item'),tr('quantity')],byRegion.map(x=>`<tr><td>${esc(x.region)}</td><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td></tr>`))}</div></div><div class="card"><h3>${tr('warehouse')}</h3>${table([tr('po'),tr('item'),tr('quantity'),tr('batch'),tr('boxes'),tr('pallets'),tr('address')],pick.map(x=>`<tr><td class="code">${esc(x.number)}</td><td>${esc(x.item_code)}</td><td>${fmt(x.outstanding_qty)}</td><td>${esc((x.batches||[]).map(b=>`${b.batch_no} (${b.quantity}, ${b.source})`).join(', '))}</td><td>${fmt(x.boxes)}</td><td>${fmt(x.pallets)}</td><td>${esc(x.address)}</td></tr>`))}</div><div class="grid"><div class="card"><h3>PO values by region</h3>${table([tr('region'),'POs',tr('value')],(report.by_region||[]).map(x=>`<tr><td>${esc(x.region)}</td><td>${fmt(x.po_count)}</td><td>${money(x.value)}</td></tr>`))}</div><div class="card"><h3>Invoice pipeline</h3>${table([tr('status'),tr('invoice'),tr('value')],(report.invoice_status||[]).map(x=>`<tr><td>${st(x.status)}</td><td>${fmt(x.count)}</td><td>${money(x.value)}</td></tr>`))}</div></div>`,tr('reports'))}
function exportReport(kind){let rows=kind==='item'?(ops.by_item||[]):(ops.by_region_item||[]).filter(x=>!regionFilter||x.region===regionFilter),keys=kind==='item'?['item_code','quantity']:['region','item_code','quantity'];downloadCSV(kind==='item'?'outstanding-by-item.csv':'outstanding-by-region-item.csv',rows,keys)}function downloadCSV(name,rows,keys){let csv=[keys.join(','),...rows.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}function exportPickList(){let rows=(ops.warehouse_pick_list||[]).filter(x=>!regionFilter||x.region===regionFilter),keys=['number','region','item_code','outstanding_qty','boxes','pallets','address'];let csv=[keys.join(','),...rows.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='warehouse-pick-list.csv';a.click();URL.revokeObjectURL(a.href)}
function previewPanel(j,action){return `<div class="alert ${j.ready?'':'danger'}">${fmt(j.rows||j.files?.length||0)} ${j.files?'files':'rows'} · ${fmt(j.error_count||0)} errors ${j.distinct_pos!==undefined?' · '+fmt(j.distinct_pos)+' POs':''}</div>${j.errors?.length?`<pre class="preview">${esc(JSON.stringify(j.errors,null,2))}</pre>`:''}${j.ready?`<button class="primary" onclick="${action}">${tr('approveAll')}</button>`:''}`}
function importsView(){let types=[['masterlist','PO Masterlist'],['due_region','Due and Region'],['sial_formatted','Sial PO Report 21 Nov 2026']];shell(`<div class="card"><h3>${tr('uploadPO')}</h3><p class="hint">${tr('pdfHelp')}</p><form class="form" onsubmit="previewPDFs(event)"><label class="file-input full">${tr('chooseFiles')}<input type="file" name="files" accept=".pdf" multiple required></label><button class="primary">${tr('preview')}</button></form><div id="pdf-preview"></div></div><div class="grid"><div class="card"><h3>${tr('mergePDF')}</h3><form class="form one" onsubmit="mergePDFs(event)"><label class="file-input">PDF<input type="file" name="files" accept=".pdf" multiple required></label><button class="secondary">${tr('mergePDF')}</button></form></div><div class="card"><h3>${tr('importWorkbook')}</h3><p class="hint">${tr('importHelp')}</p><form class="form one" onsubmit="previewSeed(event)">${select('kind',tr('workbookType'),choices(types))}<label class="file-input">XLSX<input type="file" name="file" accept=".xlsx" required></label><button class="primary">${tr('preview')}</button></form><div id="seed-preview"></div></div></div><div class="card"><h3>${tr('softCopies')}</h3><p class="hint">${tr('softCopyHelp')}</p><form class="form" onsubmit="previewSoftCopies(event)"><label class="file-input full">PDF<input type="file" name="files" accept=".pdf" multiple required></label><button class="primary">${tr('preview')}</button></form><div id="soft-copy-preview"></div></div>`,tr('imports'))}
async function previewPDFs(e){e.preventDefault();let files=[...e.target.files.files],fd=new FormData();for(let f of files)fd.append('files',f);try{let j=await api('po-pdf/bulk-preview','POST',fd);previewState={kind:'pdf',files,fingerprints:j.files.map(x=>x.fingerprint)};document.getElementById('pdf-preview').innerHTML=j.files.map(x=>`<div class="card"><h3>${esc(x.filename)} · ${esc(x.po_number||'Unknown PO')}</h3><p class="small">${tr('value')}: ${money(x.value)} · Customer PO: ${esc(x.customer_po||'—')} · ${esc(x.customer||'')}</p>${x.error?`<div class="alert danger">${esc(x.error)}</div>`:''}${(x.warnings||[]).map(y=>`<div class="alert danger">${esc(y)}</div>`).join('')}${table(['#',tr('item'),tr('quantity'),tr('due'),tr('address')],(x.items||[]).map(item=>`<tr><td>${esc(item.line_no)}</td><td>${esc(item.item_code)}</td><td>${fmt(item.quantity)}</td><td>${esc(item.schedules.map(s=>`${s.quantity} · ${s.due_date}`).join(', '))}</td><td>${esc(item.address)}</td></tr>`))}</div>`).join('')+(j.ready?`<button class="primary" onclick="approvePDFs()">${tr('approveAll')}</button>`:`<p class="alert danger">${tr('pdfWarning')}</p>`)}catch(x){toast(x.message)}}async function approvePDFs(){if(previewState?.kind!=='pdf'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();for(let f of previewState.files)fd.append('files',f);fd.set('fingerprints',JSON.stringify(previewState.fingerprints));try{let j=await api('po-pdf/bulk-approve','POST',fd);previewState=null;await refresh();toast(`${j.po_count} POs · ${j.documents_added} PDFs · ${j.duplicates_skipped} duplicates skipped`)}catch(x){toast(x.message)}}async function mergePDFs(e){e.preventDefault();let fd=new FormData();for(let f of e.target.files.files)fd.append('files',f);try{let r=await fetch('/api/po-pdf/merge',{method:'POST',headers:{'X-Logistics-Request':'1'},body:fd});if(!r.ok){let j=await r.json();throw Error(detailError(j))}let blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='merged-po-documents.pdf';a.click();URL.revokeObjectURL(a.href)}catch(x){toast(x.message)}}async function previewSeed(e){e.preventDefault();let kind=e.target.kind.value,file=e.target.file.files[0],fd=new FormData();fd.set('file',file);try{let j=await api(`seed/${kind}/preview`,'POST',fd);previewState={kind:'seed',seedKind:kind,file,fingerprint:j.fingerprint};document.getElementById('seed-preview').innerHTML=previewPanel(j,'applySeed()')}catch(x){toast(x.message)}}async function applySeed(){if(previewState?.kind!=='seed'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();fd.set('file',previewState.file);fd.set('fingerprint',previewState.fingerprint);try{let j=await api(`seed/${previewState.seedKind}/apply`,'POST',fd);await refresh();toast(`${j.rows} rows imported`)}catch(x){toast(x.message)}}
async function previewSoftCopies(e){e.preventDefault();let files=[...e.target.files.files],fd=new FormData();for(let f of files)fd.append('files',f);try{let j=await api('po-documents/bulk-preview','POST',fd);previewState={kind:'soft',files,fingerprints:j.files.map(x=>x.fingerprint)};document.getElementById('soft-copy-preview').innerHTML=`<div class="alert">${j.known_count} matched · ${j.duplicates} duplicates</div>`+table(['PDF',tr('po'),tr('status')],j.files.map(x=>`<tr><td>${esc(x.filename)}</td><td>${esc(x.po_number||'—')}</td><td>${esc(x.error||(!x.known?'Unknown PO':x.duplicate?'Duplicate':'Ready'))}</td></tr>`))+(j.ready?`<button class="primary" onclick="attachSoftCopies()">${tr('approveAll')}</button>`:'')}catch(x){toast(x.message)}}
async function attachSoftCopies(){if(previewState?.kind!=='soft'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();for(let f of previewState.files)fd.append('files',f);fd.set('fingerprints',JSON.stringify(previewState.fingerprints));try{let j=await api('po-documents/bulk-attach','POST',fd);previewState=null;await refresh();toast(`${j.documents_added} PDFs added · ${j.duplicates_skipped} duplicates skipped`)}catch(x){toast(x.message)}}
function tasksView(){
  const pos=data.pos||[],tasks=(data.tasks||[]).filter(x=>x.task_type!=='asn_booking');
  const asnRows=asnAssignments.map(x=>`<tr><td><button class="secondary" onclick="openPO(${x.po_id})">${esc(x.po_number)}</button></td><td>${esc(x.assigned_to)}</td><td>${esc(x.invoice_number)}</td><td>${esc(x.due_date||'—')}</td><td><span class="pill">${esc(x.status)}</span></td><td>${x.status==='submitted'&&user.is_admin?`<div class="actions"><button class="primary" onclick="reviewASN(${x.id},'accept')">${tr('accept')}</button><button class="secondary" onclick="reviewASN(${x.id},'return')">${tr('return')}</button></div>`:x.assigned_to===user.username&&['open','in_progress','returned'].includes(x.status)?`<button class="primary" onclick="document.getElementById('asn-${x.id}').hidden=false">${tr('submitASN')}</button>`:''}${x.status==='returned'?`<p class="hint">${esc(x.details||'')}</p>`:''}</td></tr><tr id="asn-${x.id}" hidden><td colspan="6"><form class="form" onsubmit="submitASN(event,${x.id})">${field('asn_number','ASN #','text',`value="${esc(x.asn_number||'')}"`)}${field('asn_date','ASN '+tr('date'),'date',`value="${esc(x.asn_date||'')}" required`)}${field('asn_link','ASN URL','url',`value="${esc(x.asn_link||'')}"`)}${field('remarks',tr('reason'),'text',`value="${esc(x.asn_remarks||'')}"`)}<button class="primary">${tr('submitASN')}</button></form></td></tr>`);
  const asn=`<div class="card"><h3>${tr('asnTasks')}</h3>${table([tr('po'),tr('assignedTo'),tr('invoiceNumber'),tr('due'),tr('status'),''],asnRows)}</div>`;
  const assign=user.is_admin?`<div class="card"><h3>${tr('assignTask')}</h3><form class="form" onsubmit="createTask(event)">${field('title',tr('title'),'text','required')}${field('assigned_to',tr('assignedTo'),'text','required')}${select('po_id',tr('po'),choices([['','—'],...pos.map(p=>[p.id,p.number])]))}${field('due_date',tr('due'),'date')}${field('details',tr('details'))}<button class="primary">${tr('assignTask')}</button></form></div>`:'';
  const other=`<div class="card">${table([tr('title'),tr('assignedTo'),tr('po'),tr('due'),tr('status')],tasks.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.assigned_to)}</td><td>${esc(pos.find(p=>p.id===x.po_id)?.number)}</td><td>${esc(x.due_date)}</td><td>${select('status','',choices(['open','in_progress','done'].map(y=>[y,st(y)]),x.status),`onchange="taskStatus(${x.id},this.value)"`)}</td></tr>`))}</div>`;
  shell(asn+assign+other,tr('tasks'));
}
async function submitASN(e,id){e.preventDefault();try{await api(`asn-assignments/${id}/submit`,'POST',Object.fromEntries(new FormData(e.target)));await refresh();toast(tr('submitASN'))}catch(x){toast(x.message)}}
async function reviewASN(id,action){let reason='';if(action==='return'){reason=prompt(tr('reason'))||'';if(!reason)return}if(!confirm(`${tr('confirm')}: ${tr(action)}?`))return;try{await api(`asn-assignments/${id}/review`,'POST',{action,reason});await refresh();toast(tr(action))}catch(x){toast(x.message)}}
async function createTask(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.po_id=x.po_id?Number(x.po_id):null;try{await api('tasks','POST',x);await refresh()}catch(y){toast(y.message)}}async function taskStatus(id,status){try{await api(`tasks/${id}`,'PATCH',{status});await refresh()}catch(x){toast(x.message)}}
function adminView(){if(!user?.is_admin){shell(`<div class="card"><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></div>`,tr('admin'));return}let perms=['pos_edit','inventory_edit','invoice_edit','issue_edit','task_edit','reports_view','imports_apply','users_manage'];shell(`<div class="grid"><div class="card"><h3>${tr('createUser')}</h3><form class="form" onsubmit="createUser(event)">${field('username',tr('user'),'text','required')}${field('password',tr('password'),'password','minlength="12" required')}${field('email','Email','email')}<label class="check"><input name="is_admin" type="checkbox">${tr('assistantAdmin')}</label><div class="full">${perms.map(p=>`<label class="check"><input type="checkbox" name="permission" value="${p}">${esc(p.replaceAll('_',' '))}</label>`).join('')}</div><button class="primary">${tr('createUser')}</button></form></div><div class="card"><h3>${tr('users')}</h3><div id="user-list"></div><button class="secondary" onclick="loadUsers()">Refresh</button></div></div><div class="grid"><div class="card"><h3>${tr('customStatuses')}</h3><p class="hint">Core workflow statuses must remain in the list. Add custom codes separated by commas.</p><form class="form one" onsubmit="saveStatuses(event)">${select('group',tr('status'),choices([['po',tr('status')],['invoice',tr('invoiceStage')]]),'onchange="document.querySelector(\'[name=options]\').value=statusOptions[this.value].join(\', \')"')}<label>Codes<textarea name="options">${esc((statusOptions.po||[]).join(', '))}</textarea></label><button class="primary">${tr('save')}</button></form></div><div class="card"><h3>${tr('changePassword')}</h3><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></div></div><div class="card"><h3>${tr('undoImports')}</h3><p class="hint">A backup is created before each import. Reset removes every PO and its linked work history, while preserving users and physical stock.</p><div class="actions"><button class="secondary" onclick="loadBackups()">${tr('backup')}</button><button class="danger" onclick="resetAllPOs()">${tr('resetPOs')}</button></div><div id="backup-list"></div></div>`,tr('admin'));loadUsers();loadBackups()}
async function loadBackups(){try{let b=await api('admin/backups');backups=b.backups||b;let node=document.getElementById('backup-list');if(node)node.innerHTML=table([tr('date'),tr('details'),''],backups.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.label)}</td><td><a class="button secondary" href="/api/admin/backups/${esc(x.id)}">${tr('download')}</a> <button class="secondary" onclick="restoreBackup('${esc(x.id)}')">${tr('restore')}</button></td></tr>`))}catch(x){toast(x.message)}}
async function resetAllPOs(){try{let preview=await api('admin/reset-preview');let phrase=prompt(`This deletes ${preview.pos} POs, ${preview.invoices} invoices, ${preview.linked_tasks} linked tasks and all PO history. A backup is saved first. Type RESET ALL PURCHASE ORDERS to continue.`);if(phrase!=='RESET ALL PURCHASE ORDERS')return;let j=await api('admin/reset-pos','POST',{phrase});selectedPO=null;selectedIds.clear();await refresh();toast(`PO reset complete. Backup ${j.backup_id}`)}catch(x){toast(x.message)}}
async function restoreBackup(backup_id){let phrase=prompt(`Restore backup ${backup_id}? Current data will be saved first. Type RESTORE DATABASE to continue.`);if(phrase!=='RESTORE DATABASE')return;try{await api('admin/restore-backup','POST',{backup_id,phrase});await refresh();toast(tr('restore'))}catch(x){toast(x.message)}}
async function changePassword(e){e.preventDefault();try{await api('auth/password','POST',Object.fromEntries(new FormData(e.target)));user=null;loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}async function createUser(e){e.preventDefault();let f=e.target,body={username:f.username.value,password:f.password.value,email:f.email.value,is_admin:f.is_admin.checked,permissions:[...f.querySelectorAll('[name=permission]:checked')].map(x=>x.value)};try{await api('auth/users','POST',body);await loadUsers();f.reset();toast(tr('save'))}catch(x){toast(x.message)}}async function loadUsers(){try{users=await api('auth/users');let node=document.getElementById('user-list');if(!node)return;node.innerHTML=table([tr('user'),tr('access'),tr('active'),'Action'],users.map(x=>`<tr><td>${esc(x.username)} ${x.is_admin?'★':''}</td><td>${esc(x.is_admin?tr('assistantAdmin'):x.permissions)}</td><td>${x.active?'✓':'—'}</td><td><button class="secondary" onclick="editUser(${x.id})">Edit</button></td></tr>`))}catch(x){toast(x.message)}}async function editUser(id){let x=users.find(y=>y.id===id);if(!x)return;let p=prompt('Permissions, comma separated',x.permissions);if(p===null)return;let active=confirm(x.active?'Keep this account active? Cancel will deactivate it.':'Activate this account?');try{await api(`auth/users/${id}`,'PATCH',{permissions:p.split(',').map(z=>z.trim()).filter(Boolean),active});await loadUsers();toast(tr('save'))}catch(y){toast(y.message)}}async function saveStatuses(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));try{await api('status-options','PUT',{group:x.group,options:x.options.split(',').map(y=>y.trim())});statusOptions=await api('status-options');render();toast(tr('save'))}catch(y){toast(y.message)}}
if(new URLSearchParams(location.search).has('reset')){let token=new URLSearchParams(location.search).get('reset');document.getElementById('app').innerHTML=`<div class="login card"><h3>${tr('newPassword')}</h3><form onsubmit="finishReset(event)">${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('save')}</button></form></div>`;window.finishReset=async e=>{e.preventDefault();try{await api('auth/reset-confirm','POST',{token,new_password:e.target.new_password.value});history.replaceState(null,'','/');loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}}else refresh();
